export const userRelations = relations(user, ({ many }) => ({
	sessions: many(session),
	accounts: many(account),
	oauthClients: many(oauthClient),
	oauthRefreshTokens: many(oauthRefreshToken),
	oauthAccessTokens: many(oauthAccessToken),
	oauthConsents: many(oauthConsent),
	passkeys: many(passkey),
}));

export const sessionRelations = relations(session, ({ one, many }) => ({
	user: one(user, {
		fields: [session.userId],
		references: [user.id],
	}),
	oauthRefreshTokens: many(oauthRefreshToken),
	oauthAccessTokens: many(oauthAccessToken),
}));

export const accountRelations = relations(account, ({ one }) => ({
	user: one(user, {
		fields: [account.userId],
		references: [user.id],
	}),
}));

export const oauthClientRelations = relations(oauthClient, ({ one, many }) => ({
	user: one(user, {
		fields: [oauthClient.userId],
		references: [user.id],
	}),
	oauthClientResources: many(oauthClientResource),
	oauthRefreshTokens: many(oauthRefreshToken),
	oauthAccessTokens: many(oauthAccessToken),
	oauthConsents: many(oauthConsent),
}));

export const oauthResourceRelations = relations(oauthResource, ({ many }) => ({
	oauthClientResources: many(oauthClientResource),
}));

export const oauthClientResourceRelations = relations(oauthClientResource, ({ one }) => ({
	oauthClient: one(oauthClient, {
		fields: [oauthClientResource.clientId],
		references: [oauthClient.clientId],
	}),
	oauthResource: one(oauthResource, {
		fields: [oauthClientResource.resourceId],
		references: [oauthResource.identifier],
	}),
}));

export const oauthRefreshTokenRelations = relations(oauthRefreshToken, ({ one, many }) => ({
	oauthClient: one(oauthClient, {
		fields: [oauthRefreshToken.clientId],
		references: [oauthClient.clientId],
	}),
	session: one(session, {
		fields: [oauthRefreshToken.sessionId],
		references: [session.id],
	}),
	user: one(user, {
		fields: [oauthRefreshToken.userId],
		references: [user.id],
	}),
	oauthAccessTokens: many(oauthAccessToken),
}));

export const oauthAccessTokenRelations = relations(oauthAccessToken, ({ one }) => ({
	oauthClient: one(oauthClient, {
		fields: [oauthAccessToken.clientId],
		references: [oauthClient.clientId],
	}),
	session: one(session, {
		fields: [oauthAccessToken.sessionId],
		references: [session.id],
	}),
	user: one(user, {
		fields: [oauthAccessToken.userId],
		references: [user.id],
	}),
	oauthRefreshToken: one(oauthRefreshToken, {
		fields: [oauthAccessToken.refreshId],
		references: [oauthRefreshToken.id],
	}),
}));

export const oauthConsentRelations = relations(oauthConsent, ({ one }) => ({
	oauthClient: one(oauthClient, {
		fields: [oauthConsent.clientId],
		references: [oauthClient.clientId],
	}),
	user: one(user, {
		fields: [oauthConsent.userId],
		references: [user.id],
	}),
}));

export const passkeyRelations = relations(passkey, ({ one }) => ({
	user: one(user, {
		fields: [passkey.userId],
		references: [user.id],
	}),
}));

// Preserve today's audit shape and request index; its cut is owned by the Lead.
export const signInAudit = sqliteTable(
	'sign_in_audit',
	{
		id: text('id'),
		kind: text('kind').notNull(),
		organizationId: text('organization_id'),
		actorUserId: text('actor_user_id').notNull(),
		requestId: text('request_id').notNull(),
		phase: text('phase').notNull(),
		changeKind: text('change_kind').notNull(),
		targetId: text('target_id').notNull(),
		at: integer('at').notNull(),
	},
	(table) => [
		primaryKey({ columns: [table.id] }),
		index('sign_in_audit_request_id').on(table.requestId),
		index('sign_in_audit_organization_id').on(table.organizationId),
	],
);

// r3 section 6, owner-approved (t14): retained authorization fences. Neither table has a
// foreign key, so no native deletion can cascade a fence away. Times are injected epoch ms.
export const organizationAuthorizationRevisions = sqliteTable(
	'organization_authorization_revisions',
	{
		id: text('id').primaryKey().notNull(),
		revision: integer('revision').notNull(),
		state: text('state', { enum: ['active', 'stopped', 'deleted'] }).notNull(),
		permissionPolicyDigest: text('permission_policy_digest').notNull(),
		acknowledgedRevision: integer('acknowledged_revision').default(0).notNull(),
		acknowledgedAt: integer('acknowledged_at'),
		nextAttemptAt: integer('next_attempt_at').notNull(),
		createdAt: integer('created_at').notNull(),
		updatedAt: integer('updated_at').notNull(),
	},
	(table) => [
		check('organization_revision_range', sql`${table.revision} between 1 and 9007199254740991`),
		check('organization_revision_state', sql`${table.state} in ('active', 'stopped', 'deleted')`),
		check(
			'organization_ack_range',
			sql`${table.acknowledgedRevision} between 0 and ${table.revision}`,
		),
	],
);

export const personOrganizationAuthorizationRevisions = sqliteTable(
	'person_organization_authorization_revisions',
	{
		id: text('id').primaryKey().notNull(),
		organizationId: text('organization_id').notNull(),
		personId: text('person_id').notNull(),
		revision: integer('revision').notNull(),
		state: text('state', { enum: ['active', 'inactive'] }).notNull(),
		acknowledgedRevision: integer('acknowledged_revision').default(0).notNull(),
		acknowledgedAt: integer('acknowledged_at'),
		nextAttemptAt: integer('next_attempt_at').notNull(),
		createdAt: integer('created_at').notNull(),
		updatedAt: integer('updated_at').notNull(),
	},
	(table) => [
		unique('person_authorization_pair').on(table.organizationId, table.personId),
		index('person_authorization_subjects').on(table.personId),
		check('person_revision_range', sql`${table.revision} between 1 and 9007199254740991`),
		check('person_revision_state', sql`${table.state} in ('active', 'inactive')`),
		check('person_ack_range', sql`${table.acknowledgedRevision} between 0 and ${table.revision}`),
	],
);

export const signInSchema = {
	twoFactor,
	organization,
	member,
	invitation,
	user,
	session,
	account,
	verification,
	jwks,
	oauthClient,
	oauthResource,
	oauthClientResource,
	oauthRefreshToken,
	oauthAccessToken,
	oauthConsent,
	oauthClientAssertion,
	passkey,
	deviceCode,
	signInAudit,
	organizationAuthorizationRevisions,
	personOrganizationAuthorizationRevisions,
};
